+        container.add(0.2f);
+
+        ClassWithReadOnlyObservableArrays result = (ClassWithReadOnlyObservableArrays) pb.build();
+
+        assertEquals("testLabel", result.label, "NamedArg value must be set");
+        ObservableFloatArray floatArray = result.getFloatArray();
